/* ============================================================
   APP SHELL
   ============================================================ */
export default function App() {
  const [screen, setScreen] = useState("landing");
  const [answers, setAnswers] = useState({});
  const trip = useMemo(() => buildTrip(answers), [screen]);
  const restart = () => { setAnswers({}); setScreen("landing"); };

  // Se a pessoa acabou de voltar do Mercado Pago com sucesso, pula direto
  // pro resultado desbloqueado (ver nota no README sobre completar esta parte
  // recuperando o roteiro salvo, em vez de recalculá-lo do zero).
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("status") === "paid") setScreen("unlocked");
  }, []);

  // Antes de ir pro checkout, grava as respostas do questionário no Supabase
  // pra existir um registro real do pedido, ligado ao usuário autenticado.
  const handleUnlockRequest = async () => {
    const supabase = supabaseBrowser();
    const { data: sessionData } = await supabase.auth.getSession();
    const userId = sessionData.session?.user?.id;
    if (!userId) {
      setScreen("account");
      return;
    }
    const { data, error } = await supabase
      .from("trip_answers")
      .insert({
        user_id: userId,
        countries: answers.countries,
        date_start: answers.dateStart,
        date_end: answers.dateEnd,
        flex_level: answers.flexLevel,
        adults: answers.adults,
        kids: answers.kids,
        budget: answers.budget,
        priority: answers.priority,
        pace: answers.pace,
      })
      .select()
      .single();
    if (error) {
      console.error("Erro ao salvar respostas:", error.message);
      return;
    }
    setAnswers((a) => ({ ...a, userId, tripAnswersId: data.id }));
    setScreen("checkout");
  };

  return (
    <div style={{ width: "100%", minHeight: "100vh" }}>
      <FontImports />
      {screen === "landing" && <LandingPage onStart={() => setScreen("account")} />}
      {screen === "account" && <StepAccount answers={answers} setAnswers={setAnswers} onNext={() => setScreen("destino")} onBack={restart} />}
      {screen === "destino" && <StepDestino answers={answers} setAnswers={setAnswers} onNext={() => setScreen("datas")} onBack={() => setScreen("account")} />}
      {screen === "datas" && <StepDatas answers={answers} setAnswers={setAnswers} onNext={() => setScreen("pessoas")} onBack={() => setScreen("destino")} />}
      {screen === "pessoas" && <StepPessoasOrcamento answers={answers} setAnswers={setAnswers} onNext={() => setScreen("preferencias")} onBack={() => setScreen("datas")} />}
      {screen === "preferencias" && <StepPreferencias answers={answers} setAnswers={setAnswers} onNext={() => setScreen("loading")} onBack={() => setScreen("pessoas")} />}
      {screen === "loading" && <LoadingScreen onDone={() => setScreen("blocked")} />}
      {screen === "blocked" && <BlockedResult trip={trip} onUnlock={handleUnlockRequest} onRestart={restart} />}
      {screen === "checkout" && <Checkout answers={answers} onBack={() => setScreen("blocked")} onDone={() => setScreen("unlocked")} />}
      {screen === "unlocked" && <UnlockedResult trip={trip} onPassport={restart} onStart={restart} />}
    </div>
  );
}
